'use client'

// React Imports
import { useState } from 'react'

// MUI Imports
import Box from '@mui/material/Box'

// Component Imports
import Navigation from '@components/layout/vertical/Navigation'
import NavbarContent from '@components/layout/vertical/NavbarContent'

// Type Imports
import type { ChildrenType } from '@core/types'

const DashboardLayout = ({ children }: ChildrenType) => {
  const [sidebarOpen, setSidebarOpen] = useState(false)

  return (
    <Box className='flex min-bs-dvh'>
      <Navigation
        open={sidebarOpen}
        onClose={() => setSidebarOpen(false)}
        onToggle={() => setSidebarOpen(prev => !prev)}
      />
      <Box className='flex flex-col flex-1 min-is-0'>
        {/* Navbar */}
        <Box
          component='header'
          className='sticky block-start-0 z-10'
          sx={{ backgroundColor: 'var(--mui-palette-background-default)' }}
        >
          <NavbarContent onToggleSidebar={() => setSidebarOpen(prev => !prev)} />
        </Box>

        {/* Content */}
        <Box component='main' className='flex-1 p-6'>
          {children}
        </Box>
      </Box>
    </Box>
  )
}

export default DashboardLayout
